/*
 * A043519  Numbers having three 7's in base 10.
 * https://oeis.org/A043519
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   a(n) = the n-th integer having exactly three decimal 7's
 * Range:     u8 none, u16 n <= 221, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   has_three_sevens
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* The sequence is generated by scanning numbers upwards and
   collecting those whose decimal representation contains
   precisely three '7' digits.  An incremental cache is
   maintained so that any order of calls works, and the
   computation stays linear in the number of terms needed. */
#include <stdbool.h>
#include <stddef.h>   /* for size_t */
#include "../utils/has_three_sevens.h"

/* A static cache large enough for the typical test range (≥10000 terms). */
#define CACHE_CAP 20000
static seq_t cache[CACHE_CAP];
static size_t cache_len = 0;
static seq_t next_candidate = 777;

seq_t a(idx_t n) {
    /* Ensure at least n terms are cached */
    while (cache_len < n) {
        /* Find next number with exactly three 7's */
        while (!has_three_sevens(next_candidate))
            ++next_candidate;
        /* Store it */
        cache[cache_len++] = next_candidate;
        ++next_candidate;
    }
    /* Indices in OEIS start at 1 */
    return cache[n - 1];
}
